  return Math.round((h - diskon(h)) * (1 + PAJAK));
}
// === diskon.js ===
import { PAJAK } from "./harga.js";
export function diskon(h) {
  return h > 100000 ? h * 0.1 : 0;
}
export function infoPajak() {
  return `Pajak ${PAJAK * 100}%`;
}
// === main.js ===
import { hargaAkhir } from "./harga.js";
import { infoPajak } from "./diskon.js";
console.log(hargaAkhir(50000));
console.log(hargaAkhir(200000));
console.log(infoPajak());

